    use aap:caps/types@0.1.0.{conversation-context, response-result, agent-response, llm-error};

    import aap:caps/kb-read@0.1.0;
    import aap:caps/tool-llm@0.1.0;

    export run: func(ctx: conversation-context) -> response-result;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::kb_read;
use crate::aap::caps::tool_llm::{self, Reply};

/// Upper bound on model rounds, so a model that keeps asking for tools cannot loop forever.
const MAX_ROUNDS: usize = 4;

const SYSTEM: &str = "You are a customer-support assistant. Answer the question using \
the provided knowledge. You may call the `lookup` tool to search the knowledge base.";

struct Node;

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        match answer(&ctx) {
            Ok(text) => ResponseResult::Ok(AgentResponse { text }),
            Err(message) => ResponseResult::Error(LlmError { message }),
        }
    }
}

fn answer(ctx: &ConversationContext) -> Result<String, String> {
    // `requires len(question) <= 512` holds of every input, so no length check is
    // made here: a byte-length check would diverge from Python's code-point `len`.

    let knowledge = ctx
        .knowledge
        .iter()
        .map(|k| format!("- {k}"))
        .collect::<Vec<_>>()
        .join("\n");

    let mut prompt = format!(
        "Intent: {:?}\nQuestion: {}\n\nKnowledge:\n{}",
        ctx.intent, ctx.question, knowledge
    );

    for _ in 0..MAX_ROUNDS {
        match tool_llm::generate(SYSTEM, &prompt) {
            Reply::Text(text) => return Ok(text),
            Reply::Call(req) => {
                // Only the `lookup` tool is in this node's scope.
                if req.tool != "lookup" {
                    return Err(format!("tool `{}` is not in scope", req.tool));
                }
                let hits = kb_read::lookup(&req.query);
                prompt.push_str("\n\nLookup results for ");
                prompt.push_str(&req.query);
                prompt.push_str(":\n");
                for hit in &hits {
                    prompt.push_str("- ");
                    prompt.push_str(hit);
                    prompt.push('\n');
                }
            }
        }
    }

    Err(format!("no answer after {MAX_ROUNDS} model rounds"))
}

export!(Node);
```

